+    && isRecord(inputs?.displayPromotion)
+    && isRecord(inputs?.browserNetworkSmoke)
+    && isRecord(inputs?.frontendIntegrationSmoke)
+    && isRecord(inputs?.selfAssessmentFixtures)
+    && validatorPasses(inputs?.sourceViewAssetsValidator)
+    && validatorPasses(inputs?.visualQaValidator)
+    && validatorPasses(inputs?.displayPromotionValidator);
