+
+function mapBy(items, selector) {
+  const map = new Map();
+  for (const item of asArray(items).filter(isRecord)) {
+    const key = selector(item);
+    if (isNonEmptyString(key)) map.set(key, item);
+  }
+  return map;
+}
+
+function fixtureSourceRefs(root, paths, roles) {
+  const all = sourceArtifacts(root, paths);
+  return all.filter((artifact) => roles.includes(artifact.role)).map((artifact) => ({
+    role: artifact.role,
+    path: artifact.path,
+    sha256: artifact.sha256,
+  }));
+}
+
+function zeroSideEffectReceipt() {
+  return Object.fromEntries(SIDE_EFFECT_FIELDS.map((field) => [field, 0]));
+}
+
+function sideEffectTotal(receipt) {
+  return SIDE_EFFECT_FIELDS.reduce((sum, field) => sum + numberFrom(receipt?.[field], 0), 0);
+}
+
+function sideEffectsZero(receipt) {
+  return sideEffectTotal(receipt) === 0;
+}
+
+function countBy(items, selector) {
+  const counts = {};
+  for (const item of asArray(items).filter(isRecord)) {
+    const key = String(selector(item));
+    counts[key] = (counts[key] ?? 0) + 1;
+  }
+  return Object.fromEntries(Object.entries(counts).sort(([left], [right]) => compareString(left, right)));
+}
+
+function collectStrings(value, out = []) {
+  if (typeof value === 'string') out.push(value);
+  else if (Array.isArray(value)) value.forEach((item) => collectStrings(item, out));
+  else if (isRecord(value)) Object.values(value).forEach((item) => collectStrings(item, out));
+  return out;
+}
+
+function countBannedWording(value) {
+  return collectStrings(value).reduce((sum, text) => (
