+function coverageCounts(locator) {
+  const rows = asArray(locator?.rows).filter(isRecord);
+  const complete = rows.filter((row) => row.subpart_coverage_status === 'complete').length;
+  const partial = rows.filter((row) => row.subpart_coverage_status === 'partial').length;
+  const blocked = rows.filter((row) => row.subpart_coverage_status === 'blocked').length;
+  return {
+    complete_subpart_coverage_count: complete,
+    partial_subpart_coverage_count: partial,
+    unknown_or_blocked_coverage_count: blocked,
+    partial_unknown_coverage_count: partial + blocked,
+  };
+}
