+function exposureWarningCounts(visualQa) {
+  const rows = asArray(visualQa?.question_level_visual_qa).filter(isRecord);
+  const warningRows = rows.filter((row) => row.requires_user_warning === true);
+  const byScope = countBy(warningRows, (row) => row.exposure_scope ?? 'unknown');
+  return {
+    same_page_multiple_questions: numberFrom(byScope.same_page_multiple_questions),
+    multi_page_multiple_questions: numberFrom(byScope.multi_page_multiple_questions),
+    target_question_only_with_warning: numberFrom(byScope.target_question_only),
+    warning_required_total: warningRows.length,
