+function check(id, passed, observed = {}) {
+  return { id, status: passed ? 'pass' : 'fail', observed };
+}
+
+function requiredFixtureIdsPresent(fixtures) {
+  return asArray(fixtures?.fixtures).map((fixture) => fixture.fixture_id).join('|')
+    === REQUIRED_FIXTURE_IDS.join('|');
+}
+
+function manifestDistinguishesSources(manifest) {
+  const entries = asArray(manifest?.fixture_manifest);
+  return entries.length === REQUIRED_FIXTURE_IDS.length
+    && entries.every((entry) => (
+      isRecord(entry)
+      && REQUIRED_FIXTURE_IDS.includes(entry.fixture_id)
+      && BASIS_KINDS.includes(entry.basis_kind)
+      && Array.isArray(entry.covered_required_states)
+      && entry.covered_required_states.length > 0
+      && Array.isArray(entry.source_artifact_refs)
+      && entry.source_artifact_refs.length > 0
+      && (entry.basis_kind === 'synthetic_frontend_projection'
+        ? entry.synthetic_frontend_projection === true
+        : entry.synthetic_frontend_projection === false)
+    ));
+}
+
+function wordingContractPresent(fixtures) {
+  return asArray(fixtures?.fixtures).every((fixture) => (
+    JSON.stringify(fixture.visible_wording) === JSON.stringify(REQUIRED_VISIBLE_WORDING)
+  ));
+}
+
+function preAttemptNoMsAssetRefs(fixtures, closeout) {
+  const preAttempt = asArray(fixtures?.fixtures).find((fixture) => fixture.fixture_id === 'pre_attempt_blocked');
+  const controlledRefs = asArray(preAttempt?.source_view?.controlled_asset_refs);
+  return numberFrom(preAttempt?.initial_payload?.ms_asset_ref_count) === 0
+    && controlledRefs.length === 0
+    && numberFrom(closeout?.final_counts?.pre_attempt_network_request_count) === 0
+    && numberFrom(closeout?.final_counts?.initial_payload_static_props_bundle_ms_asset_ref_count) === 0;
