+    && fixture.reveal_gate?.direct_static_fetch_allowed === false
+    && fixture.reveal_gate?.public_static_guessable_url_allowed === false
+    && numberFrom(fixture.initial_payload?.preload_prefetch_ms_asset_ref_count) === 0
+    && numberFrom(fixture.initial_payload?.route_loader_ms_asset_ref_count) === 0
+    && numberFrom(fixture.initial_payload?.client_bundle_ms_asset_ref_count) === 0
+  ));
+}
