+function revealReceiptsValid(fixtures) {
+  const allowedReceipts = new Set([
+    'submitted_answer',
+    'student_confirmed_attempt',
+    'server_side_attempt_receipt_or_submitted_answer',
+  ]);
+  return asArray(fixtures?.fixtures).every((fixture) => {
+    if (fixture.reveal_gate?.client_attempted_boolean_trusted !== false) return false;
+    if (fixture.reveal_gate?.reveal_allowed !== true) return true;
+    return fixture.reveal_gate.server_side_attempt_receipt_required === true
+      && allowedReceipts.has(fixture.reveal_gate.required_receipt);
+  });
+}
+
