+    .find((entry) => entry.fixture_id === 'document_only_no_in_app_full_document_reveal');
+  return fixture?.source_view?.locator_status === 'document_only'
+    && fixture.source_view.full_document_student_reveal_allowed === false
+    && fixture.source_view.in_app_full_document_reveal_allowed === false
+    && fixture.display?.student_ms_source_visible === false;
