+function warningCountsPresent(closeout) {
+  return numberFrom(closeout?.exposure_warning_counts?.same_page_multiple_questions) > 0
+    && numberFrom(closeout?.exposure_warning_counts?.multi_page_multiple_questions) > 0
+    && numberFrom(closeout?.exposure_warning_counts?.warning_required_total) > 0;
+}
