+function selfAssessmentLowStrength(fixtures) {
+  const fixture = asArray(fixtures?.fixtures)
+    .find((entry) => entry.fixture_id === 'self_assessment_capture_after_source_view');
+  return fixture?.self_assessment?.controls_visible_after_source_view === true
+    && fixture.self_assessment.can_raise_secure_or_exam_ready === false
+    && fixture.self_assessment.can_count_as_released_scoring_evidence === false
